<?php $this->layout('layouts/erp');$labels=['draft'=>'Rascunho','pending_approval'=>'Em aprovação','active'=>'Ativo','rejected'=>'Rejeitado','expiring'=>'Vencendo','expired'=>'Vencido','cancelled'=>'Cancelado']; ?>
<main class="page_main contract-detail"><a href="<?= url('/erp/contracts') ?>">← Voltar</a><header><h1><?= htmlspecialchars($contract->title) ?></h1><p><?= $labels[$contract->status]??$contract->status ?> · <?= date_fmt($contract->starts_at,'d/m/Y') ?><?= $contract->ends_at?' a '.date_fmt($contract->ends_at,'d/m/Y'):'' ?></p></header>
<section><h2>Documentos</h2><?php foreach($documents as $document):?><p><strong><?= htmlspecialchars($document->title) ?></strong> · <?= htmlspecialchars((string)$document->category) ?></p><?php endforeach;?><?php if($contract->status==='draft'):?><form method="post" action="<?= url('/erp/contracts/'.$contract->id) ?>"><?= csrf_input() ?><input type="hidden" name="action" value="document"><input name="title" required minlength="3" placeholder="Título do documento"><input name="category" placeholder="Categoria"><input name="file_path" maxlength="255" placeholder="Caminho privado do arquivo"><select name="visibility"><option value="internal">Interno</option><option value="managers">Gestores</option></select><button type="submit">Vincular documento</button></form><?php endif;?></section>
<section><h2>Aprovação</h2><?php foreach($steps as $step):?><p>Etapa <?= (int)$step->sequence_no ?> · aprovador #<?= (int)$step->approver_id ?> · <?= htmlspecialchars($step->status) ?><?= $step->note?' — '.htmlspecialchars($step->note):'' ?></p><?php endforeach;?><?php if($contract->status==='draft'):?><form method="post" action="<?= url('/erp/contracts/'.$contract->id) ?>"><?= csrf_input() ?><input type="hidden" name="action" value="submit"><input type="number" name="approver_1" min="1" required placeholder="ID do primeiro aprovador"><input type="number" name="approver_2" min="1" placeholder="ID do segundo aprovador"><button type="submit">Enviar para aprovação</button></form><?php elseif($contract->status==='pending_approval'):?><form method="post" action="<?= url('/erp/contracts/'.$contract->id) ?>"><?= csrf_input() ?><textarea name="note" maxlength="2000" placeholder="Nota da decisão"></textarea><button name="action" value="approve" type="submit">Aprovar etapa</button><button name="action" value="reject" type="submit" class="danger">Rejeitar</button></form><?php endif;?></section></main>
<style>.contract-detail{padding:24px}.contract-detail section{margin-top:18px;padding:18px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}.contract-detail form{display:flex;flex-wrap:wrap;gap:10px}.contract-detail input,.contract-detail select,.contract-detail textarea,.contract-detail button{padding:10px;border:1px solid #d7dce4;border-radius:7px}.contract-detail button{background:#c5a131;color:#fff;border-color:#c5a131}.contract-detail .danger{background:#b42318;border-color:#b42318}</style>
